section.source:
final HtmlInput input = (HtmlInput) page.getElementById("i1");

final Keyboard kb = new Keyboard();
kb.press(KeyboardEvent.DOM_VK_CONTROL);
kb.type('c');
kb.release(KeyboardEvent.DOM_VK_CONTROL);
input.type(kb);

final Keyboard kb = new Keyboard();

// Select all
kb.press(KeyboardEvent.DOM_VK_CONTROL);
kb.type('a');
kb.release(KeyboardEvent.DOM_VK_CONTROL);

// Copy
kb.press(KeyboardEvent.DOM_VK_CONTROL);
kb.type('c');
kb.release(KeyboardEvent.DOM_VK_CONTROL);

input.type(kb);

final Keyboard kb = new Keyboard();

// Paste
kb.press(KeyboardEvent.DOM_VK_CONTROL);
kb.type('v');
kb.release(KeyboardEvent.DOM_VK_CONTROL);

input.type(kb);
